UPDATE skills s SET category = COALESCE(s.category, v.category), description = COALESCE(s.description, v.description)
FROM (VALUES
  ('Capacity Planning', 'Quality & Measurement', 'Matching labor, equipment and shift capacity to the production plan'),
  ('Cycle Counting', 'Material Handling', 'Counting stock locations on a schedule and reconciling variances'),
  ('Design for Manufacturability', 'Software & Programming', 'Designing parts so they can be made and assembled reliably'),
  ('Design of Experiments', 'Quality & Measurement', 'Planning and analyzing structured process experiments'),
  ('ERP Inventory Transactions', 'Material Handling', 'Recording receipts, issues and transfers in an ERP system'),
  ('Ethylene Oxide Sterilization', 'Assembly & Electronics', 'Running ethylene oxide sterilization cycles for medical devices'),
  ('Grinding Wheel Dressing', 'Machining', 'Truing and dressing grinding wheels'),
  ('Helium Leak Detection', 'Quality & Measurement', 'Finding vacuum and gas line leaks with a helium leak detector'),
  ('ISO 13485 Compliance', 'Quality & Measurement', 'Medical device quality management system requirements'),
  ('LabVIEW Programming', 'Software & Programming', 'Automating tests and data acquisition in LabVIEW'),
  ('Line Balancing', 'Quality & Measurement', 'Distributing work content across stations to meet takt time'),
  ('Material Kitting', 'Material Handling', 'Picking and staging parts kits for production orders'),
  ('Measurement Uncertainty Analysis', 'Quality & Measurement', 'Estimating and reporting uncertainty of measurements and calibrations'),
  ('P&ID Reading', 'Maintenance & Repair', 'Reading piping and instrumentation diagrams'),
  ('Safety Wire Installation', 'Assembly & Electronics', 'Securing fasteners with safety wire'),
  ('Shipping Documentation', 'Material Handling', 'Preparing packing lists, bills of lading and receiving records'),
  ('Specialty Gas Handling', 'Quality & Measurement', 'Working safely with toxic, corrosive and pyrophoric process gases'),
  ('Time Study', 'Quality & Measurement', 'Measuring work content and cycle times at a workstation'),
  ('Ultrapure Water System Operation', 'Maintenance & Repair', 'Operating and monitoring ultrapure water treatment and distribution')
) AS v(name, category, description)
WHERE s.name = v.name AND (s.category IS NULL OR s.description IS NULL);

